+const newsletterForm = document.querySelector("#newsletter-form");
+const formMessage = document.querySelector("#form-message");
+const dealCountdown = document.querySelector("#deal-countdown");
+
+function renderProducts() {
+  productGrid.innerHTML = products
+    .map((product) => {
+      const oldPrice = product.oldPrice
+        ? `<span class="old-price">${product.oldPrice}</span>`
+        : "";
+
+      return `
+        <article class="product-card">
+          <span class="product-image" style="background: ${product.gradient};" aria-hidden="true"></span>
+          <div class="product-info">
+            <div class="product-topline">
+              <p class="product-category">${product.category}</p>
+              <span class="rating" aria-label="Rated ${product.rating} out of 5">Star ${product.rating}</span>
+            </div>
+            <h3>${product.name}</h3>
+            <div class="price-row">
+              <span>${product.price}${oldPrice}</span>
+              <button class="quick-add" type="button" data-product="${product.name}">Quick add</button>
+            </div>
+          </div>
+        </article>
+      `;
+    })
+    .join("");
+}
+
+function updateCountdown() {
+  const now = new Date();
+  const endOfDay = new Date(now);
+  endOfDay.setHours(23, 59, 59, 999);
+
+  const remaining = endOfDay - now;
+  const hours = Math.floor(remaining / 1000 / 60 / 60);
+  const minutes = Math.floor((remaining / 1000 / 60) % 60);
+
+  dealCountdown.textContent = `Deals end in ${hours}h ${minutes}m`;
+}
+
